// Force/moment bookkeeping for the educational overlay. Alternative decompositions are not additive.
import {V,RAD,clamp} from './constants.js';
import {boatProfile,boatScale} from './boats.js';
import {sailPoint,mainBoomPoint} from './sail-geometry.js';
import {rigResponse,mastPoint,forestayPoint,shroudPath} from './standing-rig.js';
import {flyingSheetLead} from './flying-leads.js';
import {rigDimensions} from './orc-sails.js';
import {genoaLeadGeometry,mainSheetLead,DECK} from './deck-layout.js';
import {sailFlow} from './sail-flow.js';
export const FORCE_GROUPS=[['sails','Risultanti sulle vele','Sail resultants'],['components','Lift, drag e componenti','Lift, drag and components'],['hull','Scafo, deriva e idrostatica','Hull, keel and hydrostatics'],['rig','Scotte e armo','Sheets and rig'],['moments','Momenti e coppie','Moments and couples'],['centres','Centri di applicazione','Application centres'],['pressure','Pressioni locali','Local pressures']];
const names={main:['Randa','Main'],genoa:['Vela di prua','Headsail'],spinnaker:['Spinnaker S2','S2 spinnaker'],gennaker:['Gennaker A2','A2 gennaker']};
export function loadedForceState(s,m){return{...s,boatSpeed:m.speed,rigLoads:m.rigLoads,controls:Object.fromEntries(Object.entries(s.controls).map(([type,c])=>[type,{...c,...(m.effectiveSheets?.[type]===undefined?{}:{sheet:m.effectiveSheets[type]})}]))};}
function centroid(field,k){const weight=field.cells.reduce((n,c)=>n+Math.abs(c.pa)*c.area,0);if(weight<1e-7){const area=field.cells.reduce((n,c)=>n+c.area,0);return V.mul(field.cells.reduce((p,c)=>V.add(p,V.mul(c.center,c.area*k)),[0,0,0]),1/Math.max(1e-8,area));}return V.mul(field.cells.reduce((p,c)=>V.add(p,V.mul(c.center,Math.abs(c.pa)*c.area*k)),[0,0,0]),1/weight);}
export function forceApplicationPoint(force,moment,near){const n=V.dot(force,force);if(n<1)return near;return V.add(V.mul(V.cross(force,moment),1/n),V.mul(force,V.dot(near,force)/n));}
export function buildForceDiagram(input,m){const s=loadedForceState(input,m),boat=boatProfile(s),k=boatScale(s),flow=sailFlow(s),side=Math.sign(m.awa)||1,wind=flow.direction,liftAxis=[side*wind[2],0,-side*wind[0]],items=[],point=p=>V.mul(p,k);
 const add=(id,group,label,en,origin,vector,color,estimated=false,extra={})=>items.push({id,group,label,en,origin,vector,color,estimated,kind:'force',unit:'N',magnitude:V.length(vector),...extra}),centre=(id,label,en,origin,color,estimated=true)=>items.push({id,group:'centres',label,en,origin,color,estimated,kind:'centre',unit:'m',magnitude:0});
 for(const field of m.sails){const near=centroid(field,k),cp=forceApplicationPoint(field.force,field.moment,near),[name,english]=names[field.type],f=field.force;add('air-'+field.type,'sails',name+' · forza aerodinamica',english+' · aerodynamic force',cp,f,'#256fbd');centre('cp-'+field.type,'Centro di pressione · '+name,'Centre of pressure · '+english,cp,'#256fbd');add('lift-'+field.type,'components',name+' · lift',english+' · lift',cp,V.mul(liftAxis,field.lift),'#168f9e');add('drag-'+field.type,'components',name+' · drag',english+' · drag',cp,V.mul(wind,field.drag),'#d57a38');add('drive-'+field.type,'components',name+' · spinta',english+' · drive',cp,[0,0,f[2]],'#2f916e');add('side-'+field.type,'components',name+' · forza laterale',english+' · side force',cp,[f[0],0,0],'#bc637d');add('vertical-'+field.type,'components',name+' · forza verticale',english+' · vertical force',cp,[0,f[1],0],'#8d72b1');
  for(let j=1;j<field.spanPanels;j+=Math.max(1,Math.round(field.spanPanels/4)))for(let i=1;i<field.chordPanels;i+=Math.max(1,Math.round(field.chordPanels/3))){const cell=field.cells[j*field.chordPanels+i];add(`pressure-${field.type}-${j}-${i}`,'pressure','Δp · '+name,'Δp · '+english,point(cell.center),V.mul(cell.normal,cell.pa*cell.area),'#d88c3d',false,{quiet:true});}
 }
 const near=m.sails.length?V.mul(m.sails.reduce((p,f)=>V.add(p,V.mul(centroid(f,k),f.area)),[0,0,0]),1/Math.max(1,m.area)):[0,6*k,0],ce=forceApplicationPoint(m.force,m.moment,near);if(m.sails.length)centre('ce','Centro velico risultante','Combined centre of effort',ce,'#194f91');
 const geometrical=m.sails.reduce((p,f)=>V.add(p,f.cells.reduce((v,c)=>V.add(v,V.mul(c.center,c.area*k)),[0,0,0])),[0,0,0]),physicalArea=m.sails.reduce((n,f)=>n+f.physicalArea,0);if(physicalArea>0)centre('ce-area','Centro geometrico delle vele','Geometric sail-area centre',V.mul(geometrical,1/physicalArea),'#75a0b7');
 const keelPoint=[0,-boat.draft*.55,-.25*k],rudderPoint=[0,-boat.draft*.40,-boat.length*.40],moving=clamp(m.speed/.7),rudderX=moving*(keelPoint[2]*m.force[0]-m.moment[1])/(rudderPoint[2]-keelPoint[2]),keelX=-moving*m.force[0]-rudderX,ratio=m.polarTarget>.01?m.speed/m.polarTarget:0,effectiveResistance=m.referenceReady?m.referenceScore*Math.max(0,ratio)**3:m.usefulDrive,hullResistance=effectiveResistance/Math.max(.1,m.heelFactor||1),cg=[0,-.60*k,-.15*k],weight=boat.displacement*9.81,buoyancy=Math.max(0,weight-m.force[1]),cb=[Math.sign(m.force[0])*(boat.beam*.38+boat.draft*.12)*Math.sin(m.heel*RAD),-.25*k,-.15*k];
 add('keel','hull','Deriva · reazione e drag','Keel · side reaction and drag',keelPoint,[keelX,0,-m.keelDrag],'#168b87',true);add('rudder','hull','Timone · reazione e drag','Rudder · reaction and drag',rudderPoint,[rudderX,0,-m.rudderDrag],'#56978f',true);add('hull-drag','hull','Scafo · resistenza','Hull · resistance',[0,-.25*k,.2*k],[0,0,-hullResistance],'#d57a38',true);add('weight','hull','Peso della barca','Boat weight',cg,[0,-weight,0],'#8e6daf',true,{worldDirection:true});add('buoyancy','hull','Spinta di Archimede','Buoyancy',cb,[0,buoyancy,0],'#c79d32',true,{worldDirection:true});centre('cg','G · baricentro assunto','G · assumed centre of gravity',cg,'#8e6daf');centre('cb','B · centro di carena assunto','B · assumed centre of buoyancy',cb,'#c79d32');centre('metacentre','M · metacentro assunto','M · assumed metacentre',[0,cg[1]+boat.beam*.38+boat.draft*.12,cg[2]],'#a29362');centre('clr','CD · centro di deriva assunto','CLR · assumed lateral-resistance centre',keelPoint,'#168b87');
 const moment=(id,label,en,origin,axis,value,color)=>add(id,'moments',label,en,origin,V.mul(axis,Math.sign(value)||1),color,true,{kind:'moment',unit:'N·m',magnitude:Math.abs(value),axis,value});moment('heel-moment','Momento sbandante','Heeling moment',[0,.5*k,0],[0,0,1],m.moment[2],'#c56651');moment('righting-moment','Momento raddrizzante assunto','Assumed righting moment',[0,-.1*k,0],[0,0,1],-Math.sign(m.moment[2])*m.rightingScale*Math.sin(m.heel*RAD),'#168b87');moment('yaw-moment','Momento d’imbardata','Yaw moment',[0,.25*k,0],[0,1,0],m.moment[1],'#a377ae');
 const rig=rigResponse(s),top=point(mastPoint(1,s));for(const [id,start,end,tension,label,en]of [['forestay',point(forestayPoint(1,s)),point(forestayPoint(0,s)),rig.forestayN,'Strallo · tiro assunto','Forestay · assumed tension'],['backstay',top,[0,.93*k,-4.9*k],rig.backstayN,'Paterazzo · tiro assunto','Backstay · assumed tension']])add('rig-'+id,'rig',label,en,start,V.mul(V.unit(V.sub(end,start)),tension),'#9e83b0',true);
 for(const sign of [-1,1]){const wire=shroudPath(s,sign,24),head=point(wire.at(-1)),lead=point(wire.at(-2));add('shroud-'+sign,'rig',sign<0?'Sartia sinistra · tiro assunto':'Sartia destra · tiro assunto',sign<0?'Port shroud · assumed tension':'Starboard shroud · assumed tension',head,V.mul(V.unit(V.sub(lead,head)),rig.shroudN),'#7b99b5',true);}
 if(s.foresail==='genoa'){const lead=genoaLeadGeometry(s),clew=point(lead.clew);add('jib-sheet','rig','Scotta prua · tiro stimato','Headsail sheet · estimated pull',clew,lead.sheetForce,'#4d99c8',true);add('jib-car','rig','Rinvio prua · reazione stimata','Headsail lead · estimated reaction',point(lead.ring),V.mul(lead.sheetForce,-1),'#8f77a8',true);}
 if(s.main){const attach=point(mainBoomPoint(DECK.mainSheetAttachment,s)),lead=point(mainSheetLead(s)),main=m.sails.find(f=>f.type==='main'),direction=V.unit(V.sub(lead,attach)),tension=V.length(main?.force||[0,0,0])*(.25+.55*s.controls.main.sheet/100);add('main-sheet','rig','Scotta randa · tiro stimato','Mainsheet · estimated pull',attach,V.mul(direction,tension),'#df9869',true);}
 const rope=(id,label,en,from,to,tension,color='#9b80ad')=>add(id,'rig',label,en,point(from),V.mul(V.unit(V.sub(to,from)),Math.max(0,tension)),color,true);
 for(const field of m.sails){const type=field.type,head=sailPoint(type,1,0,s),exit=mastPoint(type==='genoa'?rigDimensions(s).foreFraction:1,s),load=V.length(field.force),end=[exit[0],Math.max(exit[1],head[1]+.12),exit[2]],c=s.controls[type];rope('halyard-'+type,'Drizza · '+names[type][0],'Halyard · '+names[type][1],head,end,load*(.35+.45*c.halyard/100));if(type==='spinnaker'||type==='gennaker'){const clew=sailPoint(type,0,1,s),tack=sailPoint(type,0,0,s);rope('sheet-'+type,'Scotta · '+names[type][0],'Sheet · '+names[type][1],clew,flyingSheetLead(type,s),load*(.2+.65*c.sheet/100),'#8b80bf');if(type==='gennaker')rope('tack-a2','Mura A2 · tiro stimato','A2 tack · estimated pull',tack,[0,.95,tack[2]],load*(.25+.5*c.tack/100),'#b77e9e');else{const windward=-(Math.sign(s.windAngle)||1);rope('guy-s2','Braccio S2 · tiro stimato','S2 guy · estimated pull',tack,[-windward*1.55,.98,-2.2],load*(.3+.55*c.brace/100),'#bf9a52');const root=mastPoint(.65,s);rope('pole-up','Caricalto · tiro stimato','Topping lift · estimated pull',tack,root,load*.20*(c.poleLift/100),'#8aa34e');rope('pole-down','Caricabasso · tiro stimato','Downhaul · estimated pull',tack,[0,.96,rigDimensions(s).mastZ+.7],load*.20*(1-c.poleLift/100),'#a6ae63');}}if(type==='main'){const root=mastPoint(0,s),clew=sailPoint('main',0,1,s);rope('vang','Vang · tiro stimato','Vang · estimated pull',mainBoomPoint(.34,s),[root[0],1.22,root[2]],load*.5*c.vang/100,'#b29566');rope('outhaul','Base randa · tiro stimato','Outhaul · estimated pull',clew,mainBoomPoint(1,s),load*.3*c.outhaul/100,'#75a286');rope('cunningham','Cunningham · tiro stimato','Cunningham · estimated pull',sailPoint('main',.04,0,s),[root[0],1.26,root[2]],load*.2*c.cunningham/100,'#b981ac');}}
 const forceBalance=[m.force[0]+keelX+rudderX,m.force[1]-weight+buoyancy,m.force[2]-hullResistance-m.keelDrag-m.rudderDrag];add('net-force','components','Risultante esterna stimata','Estimated net external force',cg,forceBalance,'#b45170',true);
 return{items,centres:items.filter(x=>x.kind==='centre'),forceBalance,scaleDescription:'logarithmic',referencePoint:[0,0,0]};
}
